// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240 px cone.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /W4 /O2 aim.cpp /Fe:aim_test.exe
//
// Exported surface:
//   bool  WorldToScreen(const Vec3& world, const ViewParams& vp, Vec2& out)
//       -- projects a 3-D world position to 2-D screen pixels; returns false when behind camera.
//   Vec2  ComputeAimDelta(const Vec3& headWS, const ViewParams& vp, float smoothFactor)
//       -- returns a smoothed (dx,dy) crosshair correction clamped to a 240 px cone radius.
//          smoothFactor in [0,1]: 0 = no movement, 1 = instant snap.

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <algorithm>

// ---------------------------------------------------------------------------
// Math primitives
// ---------------------------------------------------------------------------

struct Vec2 {
    float x, y;
    Vec2() : x(0.f), y(0.f) {}
    Vec2(float x_, float y_) : x(x_), y(y_) {}
    Vec2 operator+(const Vec2& o) const { return {x + o.x, y + o.y}; }
    Vec2 operator-(const Vec2& o) const { return {x - o.x, y - o.y}; }
    Vec2 operator*(float s)        const { return {x * s,   y * s};   }
    float length() const { return std::sqrtf(x * x + y * y); }
};

struct Vec3 {
    float x, y, z;
    Vec3() : x(0.f), y(0.f), z(0.f) {}
    Vec3(float x_, float y_, float z_) : x(x_), y(y_), z(z_) {}
    Vec3 operator-(const Vec3& o) const { return {x - o.x, y - o.y, z - o.z}; }
    float dot(const Vec3& o) const { return x * o.x + y * o.y + z * o.z; }
};

// Row-major 4x4 (matches DirectX / game convention)
struct Mat4 {
    float m[4][4];
};

// ---------------------------------------------------------------------------
// View parameters supplied by the caller each frame
// ---------------------------------------------------------------------------

struct ViewParams {
    Mat4  viewProj;      // combined view-projection matrix
    float screenW;       // viewport width  in pixels
    float screenH;       // viewport height in pixels
};

// ---------------------------------------------------------------------------
// WorldToScreen
//   Projects `world` through `vp.viewProj`, performs perspective divide,
//   maps NDC [-1,1] to pixel coordinates, and writes the result to `out`.
//   Returns false (and leaves `out` undefined) when the point is behind
//   the near plane (w <= 0).
// ---------------------------------------------------------------------------
bool WorldToScreen(const Vec3& world, const ViewParams& vp, Vec2& out)
{
    const Mat4& m = vp.viewProj;

    // Multiply [x y z 1] by the 4x4 view-projection matrix.
    float clipX = world.x * m.m[0][0] + world.y * m.m[1][0]
                + world.z * m.m[2][0] +           m.m[3][0];
    float clipY = world.x * m.m[0][1] + world.y * m.m[1][1]
                + world.z * m.m[2][1] +           m.m[3][1];
    float clipW = world.x * m.m[0][3] + world.y * m.m[1][3]
                + world.z * m.m[2][3] +           m.m[3][3];

    if (clipW <= 0.f)
        return false;   // behind near plane

    // Perspective divide -> NDC in [-1, 1]
    float ndcX =  clipX / clipW;
    float ndcY = -clipY / clipW;    // flip Y: NDC +Y is up, screen +Y is down

    // Map to pixel space
    out.x = (ndcX + 1.f) * 0.5f * vp.screenW;
    out.y = (ndcY + 1.f) * 0.5f * vp.screenH;
    return true;
}

// ---------------------------------------------------------------------------
// ComputeAimDelta
//   1. Projects the entity's head position to screen space.
//   2. Computes the raw delta from the screen centre to that pixel.
//   3. Clamps the delta to a 240 px cone radius.
//   4. Applies exponential smoothing via `smoothFactor`.
//
//   smoothFactor in [0, 1]:
//     0.0 -> crosshair never moves
//     1.0 -> instant snap to target
//   Values around 0.08-0.15 produce a natural-feeling glide.
//
//   Returns the (dx, dy) the caller should add to the current cursor position.
//   Returns {0,0} if the head is off-screen or outside the cone.
// ---------------------------------------------------------------------------
static constexpr float kConeRadiusPx = 240.f;

Vec2 ComputeAimDelta(const Vec3& headWS, const ViewParams& vp, float smoothFactor)
{
    Vec2 headSS;
    if (!WorldToScreen(headWS, vp, headSS))
        return {};

    // Screen centre
    Vec2 centre(vp.screenW * 0.5f, vp.screenH * 0.5f);

    // Raw delta from crosshair (screen centre) to projected head
    Vec2 raw = headSS - centre;

    // Discard targets outside the 240 px cone
    float dist = raw.length();
    if (dist > kConeRadiusPx || dist < 0.001f)
        return {};

    // Clamp smoothFactor to a safe range so the caller can't pass garbage
    float sf = std::max(0.f, std::min(smoothFactor, 1.f));

    // Exponential-style linear interpolation toward the raw delta.
    // Each frame the crosshair closes `sf` fraction of the remaining gap.
    Vec2 delta = raw * sf;

    return delta;
}

// ---------------------------------------------------------------------------
// Smoke test – compiled only when /DAIM_SMOKE is defined
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE

#include <cstdio>
#include <cstring>

// Build an orthographic-ish identity view-projection for quick testing.
static ViewParams MakeTestView(float w, float h)
{
    ViewParams vp{};
    vp.screenW = w;
    vp.screenH = h;
    // Identity matrix – world units == NDC units (useful only for near-origin points)
    std::memset(&vp.viewProj, 0, sizeof(vp.viewProj));
    vp.viewProj.m[0][0] = 1.f;
    vp.viewProj.m[1][1] = 1.f;
    vp.viewProj.m[2][2] = 1.f;
    vp.viewProj.m[3][3] = 1.f;
    return vp;
}

int main()
{
    const float W = 1920.f, H = 1080.f;
    ViewParams vp = MakeTestView(W, H);

    // --- WorldToScreen basic check ---
    // A point at the origin in NDC should land at the screen centre.
    Vec2 ss;
    Vec3 origin(0.f, 0.f, 0.f);
    bool visible = WorldToScreen(origin, vp, ss);
    printf("WorldToScreen(0,0,0): visible=%d  screen=(%.1f, %.1f)  expected=(%.1f, %.1f)\n",
           (int)visible, ss.x, ss.y, W * 0.5f, H * 0.5f);

    // A point at world (0.5, 0.5, 0) should map to (75%, 25%) in this identity setup
    // NDC x=0.5 -> screen x = (0.5+1)/2 * W = 0.75*W
    // NDC y=-0.5 (flipped) -> screen y = (-0.5+1)/2 * H = 0.25*H  (wait: ndcY = -clipY)
    // clipY = 0.5, ndcY = -0.5, screen y = (-0.5+1)/2*H = 0.25*H
    Vec3 p(0.5f, 0.5f, 0.f);
    visible = WorldToScreen(p, vp, ss);
    printf("WorldToScreen(0.5,0.5,0): visible=%d  screen=(%.1f, %.1f)  expected=(%.1f, %.1f)\n",
           (int)visible, ss.x, ss.y, 0.75f * W, 0.25f * H);

    // Behind-camera test (w <= 0 for negative w; force by negating z with m[2][3]=-1)
    ViewParams vpNeg = vp;
    vpNeg.viewProj.m[2][3] = -1.f;   // clipW = z*(-1) + 1; for z=2 -> clipW=-1
    Vec3 behind(0.f, 0.f, 2.f);
    visible = WorldToScreen(behind, vpNeg, ss);
    printf("WorldToScreen behind camera: visible=%d  expected=0\n", (int)visible);

    // --- ComputeAimDelta checks ---
    // Head exactly at screen centre -> delta == (0,0)
    Vec2 delta = ComputeAimDelta(origin, vp, 1.0f);
    printf("AimDelta at centre (smooth=1): (%.3f, %.3f)  expected=(0,0)\n", delta.x, delta.y);

    // Head slightly off-centre, within cone, smooth=1 -> delta == raw
    // NDC (0.1, 0) -> screen x = (0.1+1)/2 * 1920 = 1056,  screen y = centre
    Vec3 slight(0.1f, 0.f, 0.f);
    delta = ComputeAimDelta(slight, vp, 1.0f);
    float expectedDx = 1056.f - 960.f;  // 96 px
    printf("AimDelta slight right (smooth=1): (%.1f, %.1f)  expected=(%.1f, 0)\n",
           delta.x, delta.y, expectedDx);

    // Same target, smooth=0.5 -> delta should be half
    delta = ComputeAimDelta(slight, vp, 0.5f);
    printf("AimDelta slight right (smooth=0.5): (%.1f, %.1f)  expected=(%.1f, 0)\n",
           delta.x, delta.y, expectedDx * 0.5f);

    // Target outside 240 px cone -> (0,0)
    Vec3 farAway(0.9f, 0.f, 0.f);   // NDC 0.9 -> screen 1824 -> delta = 864 px > 240
    delta = ComputeAimDelta(farAway, vp, 1.0f);
    printf("AimDelta outside cone: (%.1f, %.1f)  expected=(0,0)\n", delta.x, delta.y);

    return 0;
}
#endif // AIM_SMOKE
